mapper.select:
SELECT

FROM project_change
WHERE 1=1
AND deleted = 0

    AND project_id = #{param.projectId}


    AND change_no LIKE CONCAT('%', #{param.changeNo}, '%')


    AND change_title LIKE CONCAT('%', #{param.changeTitle}, '%')


    AND change_type = #{param.changeType}


    AND change_level = #{param.changeLevel}


    AND change_status = #{param.changeStatus}


    AND priority = #{param.priority}


    AND is_urgent = #{param.isUrgent}


    AND applicant_id = #{param.applicantId}


    AND applicant_name LIKE CONCAT('%', #{param.applicantName}, '%')


    AND reviewer_id = #{param.reviewerId}


    AND approver_id = #{param.approverId}


    AND implementer_id = #{param.implementerId}


    AND cost_impact >= #{param.minCostImpact}


    AND cost_impact <= #{param.maxCostImpact}


    AND schedule_impact >= #{param.minScheduleImpact}


    AND schedule_impact <= #{param.maxScheduleImpact}


    AND apply_time >= #{param.applicationStartDate}


    AND apply_time <= #{param.applicationEndDate}


    AND implement_start_time >= #{param.implementationStartDate}


    AND implement_end_time <= #{param.implementationEndDate}


    AND create_time >= #{param.createStartTime}


    AND create_time <= #{param.createEndTime}


    AND create_by = #{param.createBy}


    AND (change_no LIKE CONCAT('%', #{param.keyword}, '%')
         OR change_title LIKE CONCAT('%', #{param.keyword}, '%')
         OR change_content LIKE CONCAT('%', #{param.keyword}, '%')
         OR applicant_name LIKE CONCAT('%', #{param.keyword}, '%')
         OR impact_analysis LIKE CONCAT('%', #{param.keyword}, '%')
         OR remarks LIKE CONCAT('%', #{param.keyword}, '%'))

ORDER BY create_time DESC, id DESC

SELECT

FROM project_change
WHERE change_no = #{changeNo}
AND deleted = 0

    AND id != #{excludeId}

LIMIT 1

SELECT
FROM project_change WHERE deleted = 0 AND (change_no LIKE CONCAT('%', #{keyword}, '%') OR change_title LIKE CONCAT('%', #{keyword}, '%') OR change_content LIKE CONCAT('%', #{keyword}, '%') OR applicant_name LIKE CONCAT('%', #{keyword}, '%') OR impact_analysis LIKE CONCAT('%', #{keyword}, '%')) ORDER BY create_time DESC
LIMIT #{limit}

SELECT COUNT(*) as totalCount, COUNT(CASE WHEN change_status = 1 THEN 1 END) as draftCount, COUNT(CASE WHEN change_status = 2 THEN 1 END) as pendingReviewCount, COUNT(CASE WHEN change_status = 3 THEN 1 END) as inReviewCount, COUNT(CASE WHEN change_status = 4 THEN 1 END) as approvedCount, COUNT(CASE WHEN change_status = 5 THEN 1 END) as rejectedCount, COUNT(CASE WHEN change_status = 6 THEN 1 END) as implementingCount, COUNT(CASE WHEN change_status = 7 THEN 1 END) as completedCount, COUNT(CASE WHEN change_status = 8 THEN 1 END) as cancelledCount, COALESCE(SUM(cost_impact), 0) as totalCostImpact, COALESCE(SUM(schedule_impact), 0) as totalScheduleImpact, COALESCE(AVG(completion_rate), 0) as avgCompletionRate FROM project_change WHERE 1=1 AND deleted = 0
AND project_id = #{param.projectId}
AND change_type = #{param.changeType}
AND change_status = #{param.changeStatus}
AND applicant_id = #{param.applicantId}
AND create_time >= #{param.createStartTime}
AND create_time <= #{param.createEndTime}

SELECT
    change_type as changeType,
    COUNT(*) as count,
    COALESCE(SUM(cost_impact), 0) as totalCostImpact,
    COALESCE(AVG(completion_rate), 0) as avgCompletionRate
FROM project_change
WHERE 1=1

    AND project_id = #{param.projectId}


    AND change_status = #{param.changeStatus}


    AND create_time >= #{param.createStartTime}


    AND create_time <= #{param.createEndTime}

GROUP BY change_type
ORDER BY count DESC

SELECT
    change_status as changeStatus,
    COUNT(*) as count,
    COALESCE(SUM(cost_impact), 0) as totalCostImpact,
    COALESCE(AVG(completion_rate), 0) as avgCompletionRate
FROM project_change
WHERE 1=1

    AND project_id = #{param.projectId}


    AND change_type = #{param.changeType}


    AND create_time >= #{param.createStartTime}


    AND create_time <= #{param.createEndTime}

GROUP BY change_status
ORDER BY change_status

SELECT
    priority,
    COUNT(*) as count,
    COALESCE(SUM(cost_impact), 0) as totalCostImpact,
    COALESCE(AVG(completion_rate), 0) as avgCompletionRate
FROM project_change
WHERE 1=1

    AND project_id = #{param.projectId}


    AND change_status = #{param.changeStatus}


    AND create_time >= #{param.createStartTime}


    AND create_time <= #{param.createEndTime}

GROUP BY priority
ORDER BY priority DESC

SELECT DATE_FORMAT(apply_time, '%Y-%m') as month, COUNT(*) as count, COUNT(CASE WHEN change_status = 7 THEN 1 END) as completedCount, COALESCE(SUM(cost_impact), 0) as totalCostImpact, COALESCE(AVG(completion_rate), 0) as avgCompletionRate FROM project_change WHERE apply_time >= DATE_SUB(SYSDATE, INTERVAL 12 MONTH)
AND project_id = #{param.projectId}
AND change_type = #{param.changeType}
GROUP BY DATE_FORMAT(apply_time, '%Y-%m') ORDER BY month

SELECT project_id as projectId, COUNT(*) as count, COUNT(CASE WHEN change_status = 7 THEN 1 END) as completedCount, COALESCE(SUM(cost_impact), 0) as totalCostImpact, COALESCE(SUM(schedule_impact), 0) as totalScheduleImpact, COALESCE(AVG(completion_rate), 0) as avgCompletionRate FROM project_change WHERE 1=1
AND change_type = #{param.changeType}
AND change_status = #{param.changeStatus}
AND create_time >= #{param.createStartTime}
AND create_time <= #{param.createEndTime}
GROUP BY project_id ORDER BY count DESC

SELECT
    applicant_id as applicantId,
    applicant_name as applicantName,
    COUNT(*) as count,
    COUNT(CASE WHEN change_status = 7 THEN 1 END) as completedCount,
    COALESCE(SUM(cost_impact), 0) as totalCostImpact,
    COALESCE(AVG(completion_rate), 0) as avgCompletionRate
FROM project_change
WHERE 1=1

    AND project_id = #{param.projectId}


    AND change_type = #{param.changeType}


    AND change_status = #{param.changeStatus}


    AND create_time >= #{param.createStartTime}


    AND create_time <= #{param.createEndTime}

GROUP BY applicant_id, applicant_name
ORDER BY count DESC

SELECT COALESCE(SUM(cost_impact), 0)
FROM project_change
WHERE 1=1

    AND project_id = #{param.projectId}


    AND change_type = #{param.changeType}


    AND change_status = #{param.changeStatus}


    AND create_time >= #{param.createStartTime}


    AND create_time <= #{param.createEndTime}

SELECT COALESCE(SUM(schedule_impact), 0)
FROM project_change
WHERE 1=1

    AND project_id = #{param.projectId}


    AND change_type = #{param.changeType}


    AND change_status = #{param.changeStatus}


    AND create_time >= #{param.createStartTime}


    AND create_time <= #{param.createEndTime}

SELECT COALESCE(AVG(completion_rate), 0)
FROM project_change
WHERE 1=1

    AND project_id = #{param.projectId}


    AND change_type = #{param.changeType}


    AND change_status = #{param.changeStatus}


    AND create_time >= #{param.createStartTime}


    AND create_time <= #{param.createEndTime}

SELECT
    CASE
        WHEN COUNT(*) = 0 THEN 0
        ELSE ROUND(COUNT(CASE WHEN change_status = 7 THEN 1 END) * 100.0 / COUNT(*), 2)
    END
FROM project_change
WHERE 1=1

    AND project_id = #{param.projectId}


    AND change_type = #{param.changeType}


    AND create_time >= #{param.createStartTime}


    AND create_time <= #{param.createEndTime}

SELECT COUNT(*) as totalChanges, COUNT(CASE WHEN cost_impact > 0 THEN 1 END) as costIncreaseCount, COUNT(CASE WHEN cost_impact < 0 THEN 1 END) as costDecreaseCount, COUNT(CASE WHEN schedule_impact > 0 THEN 1 END) as scheduleDelayCount, COUNT(CASE WHEN schedule_impact < 0 THEN 1 END) as scheduleAdvanceCount, COALESCE(SUM(CASE WHEN cost_impact > 0 THEN cost_impact END), 0) as totalCostIncrease, COALESCE(SUM(CASE WHEN cost_impact < 0 THEN ABS(cost_impact) END), 0) as totalCostDecrease, COALESCE(SUM(CASE WHEN schedule_impact > 0 THEN schedule_impact END), 0) as totalScheduleDelay, COALESCE(SUM(CASE WHEN schedule_impact < 0 THEN ABS(schedule_impact) END), 0) as totalScheduleAdvance, COALESCE(AVG(ABS(cost_impact)), 0) as avgCostImpact, COALESCE(AVG(ABS(schedule_impact)), 0) as avgScheduleImpact FROM project_change WHERE 1=1
AND project_id = #{param.projectId}
AND change_type = #{param.changeType}
AND change_status = #{param.changeStatus}
AND create_time >= #{param.createStartTime}
AND create_time <= #{param.createEndTime}

SELECT COUNT(*) as totalChanges, COUNT(CASE WHEN change_status = 7 THEN 1 END) as completedChanges, COUNT(CASE WHEN change_status = 5 THEN 1 END) as rejectedChanges, COUNT(CASE WHEN change_status = 8 THEN 1 END) as cancelledChanges, COALESCE(AVG(CASE WHEN change_status = 7 THEN completion_rate END), 0) as avgCompletionRate, COALESCE(AVG(CASE WHEN change_status = 7 AND implement_end_time IS NOT NULL AND implement_start_time IS NOT NULL THEN DATEDIFF(implement_end_time, implement_start_time) END), 0) as avgImplementationDelay, COUNT(CASE WHEN priority >= 4 THEN 1 END) as highPriorityCount, COUNT(CASE WHEN is_urgent = 1 THEN 1 END) as urgentCount, COUNT(CASE WHEN priority >= 4 AND change_status = 7 THEN 1 END) as highPriorityCompletedCount, COUNT(CASE WHEN is_urgent = 1 AND change_status = 7 THEN 1 END) as urgentCompletedCount FROM project_change WHERE 1=1
AND project_id = #{param.projectId}
AND change_type = #{param.changeType}
AND create_time >= #{param.createStartTime}
AND create_time <= #{param.createEndTime}

SELECT

FROM project_change
WHERE 1=1

    AND project_id = #{param.projectId}


    AND change_type = #{param.changeType}


    AND change_status = #{param.changeStatus}


    AND create_time >= #{param.createStartTime}


    AND create_time <= #{param.createEndTime}

ORDER BY create_time DESC

SELECT COUNT(1) > 0
FROM project_change
WHERE change_no = #{changeNo}

    AND id != #{excludeId}

mapper.update:
UPDATE project_change
SET change_status = #{changeStatus},
    update_time = SYSDATE

    , update_by = #{updateBy}

WHERE id IN

    #{id}
